"""Katyayani v1 (pooled systems) `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys

NAMES = {"ob": "Online Boutique", "ss": "Sock Shop", "tt": "Train Ticket", "live": "Live stack (RP-19)"}


def cell(c: dict | None) -> str:
    if not c:
        return "—"
    lo, hi = c["ci95"]
    return f"{c['value']:.3f} [{lo:.3f}, {hi:.3f}]"


def main(path: str) -> int:
    sys.stdout.reconfigure(encoding="utf-8")
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    out = [
        "<!-- Generated by packages/sati/sati/rca/pooledreport.py from the training workflow. Do not edit by hand. -->\n",
        "# Katyayani v1 — does real data from one more system help on the others?\n",
        f"Four systems with real fault injections: RCAEval (revision `{r['rcaeval_revision'][:7]}`, suites "
        f"{', '.join(r['train_suites'])}) and the live stack. Each is held out in turn. On the same held-out cases, "
        "**v0** is trained on the other RCAEval systems only, and **v1** also on the live stack. Paired McNemar on "
        "RCA@1.\n",
        "| Held out | Cases | v0: other RCAEval systems | v1: + live stack | Only v1 right | Only v0 right | p | "
        "Loudest service |",
        "|---|---:|---:|---:|---:|---:|---:|---:|",
    ]
    for system, row in r["systems"].items():
        p = row.get("paired")
        pval = f"{p['p']:.2g}" if p else "—"
        out.append(f"| {NAMES.get(system, system)} | {row['cases']} | {cell(row['v0 (other RCAEval systems)'])} | "
                   f"{cell(row.get('v1 (+ live stack)'))} | {p['only_v1'] if p else '—'} | "
                   f"{p['only_v0'] if p else '—'} | {pval} | {cell(row['loudest'])} |")
    out += ["", "Held out, the live stack has no v1 row: its v0 *is* the zero-shot transfer from RCAEval "
            f"([katyayani-live.md](katyayani-live.md)). {r['features']} features, the same for every system. "
            f"Run time {r['seconds']} s."]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
